import prepare as R
from collections import defaultdict
from pathlib import Path
import numpy as np,json,html
def safe(a,d=3):
 a=np.asarray(a);return np.where(np.isfinite(a),np.round(a,d),np.nan).tolist()
def clean(x):
 if isinstance(x,list):return [clean(v) for v in x]
 if isinstance(x,dict):return {k:clean(v) for k,v in x.items()}
 if isinstance(x,float) and not np.isfinite(x):return None
 return x
def main():
 ver=R.read(R.U/'INTEGRATION_VERIFIED.json');res=R.read(R.U/'PAIRS_DONE.json');pre=R.read(R.U/'PREPARED.json');refs=R.read(R.U/'REFERENCES_VERIFIED.json');causes=R.read(R.U/'CAUSES.json')['counts'];by={r['clip_id']:r for r in pre['rows']};queries={};cc=res['counts'];ic=pre['counts']
 for r in res['rows']:
  z=R.load(r['pair']);q=R.load(by[r['query']]['output']);ref=R.load(by[r['reference']]['output']);core=ref['core'];ix=np.flatnonzero(core);n=len(ref['core']);lo=np.floor(z['phase_old']).astype(int);hi=np.ceil(z['phase_old']).astype(int);qstate0=q['state_after'][lo];qstate1=q['state_after'][hi];rstate=ref['state_after'];qs=np.where(qstate0==qstate1,qstate0,6);qy=q['yolo_conflict'][lo]|q['yolo_conflict'][hi];state=np.concatenate([qs,np.zeros((n,2,8),np.uint8)],-1);rs=np.concatenate([rstate,np.zeros((n,2,8),np.uint8)],-1)
  item=dict(reference=r['reference'],reference_id=by[r['reference']]['signer_id'],time=safe(ref['timestamp_us'][ix]/1e6),query_time=safe(np.interp(z['phase_old'][ix],np.arange(len(q['core'])),q['timestamp_us']/1e6)),difference=clean(safe(z['point_delta'][ix])),raw=z['point_ok'][ix].astype(int).tolist(),before=z['point_corroborated_before'][ix].astype(int).tolist(),after=z['point_corroborated_after'][ix].astype(int).tolist(),query_state=state[ix].tolist(),reference_state=rs[ix].tolist(),yolo_audit=qy[ix].astype(int).tolist(),counts=r['counts'])
  queries.setdefault(r['word_code'],dict(word=r['word_code'],label=r['label'],query=r['query'],query_id=by[r['query']]['signer_id'],references=[]))['references'].append(item)
 assert len(queries)==100 and all(len(q['references'])==2 for q in queries.values());data=sorted(queries.values(),key=lambda r:r['word']);R.write(R.U/'VIEW_DATA.json',data)
 def pct(a,b):return f'{100*a/b:.1f}%' if b else '계산 불가'
 text=f'''공개 100단어·300영상의 참고별 비교 근거 연결

무엇을 바꿨나
원본 관절 좌표·좌우 배정·TCN·DTW 원래 차이값은 그대로 두고, 각도별로 현재 영상에서도 근거를 확인했는지를 별도로 연결했다. 한 단어의 공개 영상 하나를 서로 다른 기록ID 참고 두 개와 각각 비교했다. 평균 손 모양이나 유리한 참고 하나를 만들지 않았다.

실제 범위
공개 TRAIN100단어·300영상·200비교쌍. 이전100영상 재실행 없이 사용하고 새 참고200영상/{refs['counts']['frame_targets']:,}장면을 MP로 재확인했다. 학습0·TCN재채점0·운영교체0. 사용자·멘토·추가199/200자료 접근0.

연결 결과
참고의 주석 핵심구간에 양손15개 각도를 펼친 고정 확인칸 {cc['angle_domain']:,}개. 이 칸은 실제로 반드시 써야 하는 손·동작을 뜻하지 않는다.
원본 좌표로 순간 차이를 계산할 수 있는 칸 {cc['raw_point_angles']:,}개는 그대로 보존.
아래의 이전0은 예전DTW가 없었거나 비교를 전혀 못했다는 뜻이 아니다. 기존 재검출은 손 전체 미검출 복구용이어서, 이미 보이는 손에 이번처럼 전체이미지+확대이미지+원본위치 검사를 모두 갖춘 근거가 없었다는 뜻이다.
양쪽 영상 모두 현재 이미지 근거까지 연결된 순간각도: {cc['point_before']:,} → {cc['point_after']:,}. 원본 순간 비교 가능칸 대비 {pct(cc['point_after'],cc['raw_point_angles'])}이며 정확도가 아니다. 추가 {cc['point_added']:,}, 기존 근거 철회 {cc['point_withdrawn']:,}.
앞·현재·뒤와 사이 구간 전체가 연속 확인된 각도: {cc['sequence_before']:,} → {cc['sequence_after']:,}. 원본 연속 비교 가능칸 {cc['raw_sequence_angles']:,} 대비 {pct(cc['sequence_after'],cc['raw_sequence_angles'])}. 추가 {cc['sequence_added']:,}, 철회 {cc['sequence_withdrawn']:,}.

YOLO의 역할
이전100영상에서 얻은 YOLO 불일치는 별도 감사 표시로 유지했다. YOLO 결과가 이상하다는 이유로 MP 근거나 원본 좌표를 일괄 삭제하지 않는다. 새 참고200개에는 동일한 MP 재확인을 적용했다. 지난 동일화면위치·크기 검산에서 YOLO의 추가 핵심구간 손가락 근거가0이었으므로, YOLO로 정밀손가락교정이 좋아졌다고 주장하지 않는다.

검증
저장 결과의 각도·현재이미지 근거·원본좌표·고정 참고범위·시간대응을 별도 수식으로 검산했다. 300입력/200쌍 통과. 한각도 숨김과 한손 숨김 각각 {ver['negative_controls'].get('single_angle_no_false_zero_or_neighbor_loss',0)}개 고정경로 시험에서 해당 부분은 미관측으로 남고 이웃각도·팔·반대손은 유지됐다. 이는 같은 Codex의 별도 계산이며 독립 사람 정답이 아니다.

남은 문제
추가 이미지 근거가 부족한 순간각도 {causes['uncorroborated_point_angles']:,}칸 중 {causes['only_not_rechecked']:,}칸({pct(causes['only_not_rechecked'],causes['uncorroborated_point_angles'])})은 필요한 재확인을 호출하지 않은 것만이 원인이다. 나머지는 영상쌍부족·좌우불확실·모양/위치불일치가 하나 이상 포함된다. 이 수치를 동작 오답률로 바꾸면 안 된다.
재확인 호출이 없는 시간은 틀린 동작이 아니다. 정상 손내림·한손 동작·교차에 새로운 오류 판정을 붙이지 않았다. 원래 좌표와 시간대응이 같다는 보존 검증이지, 모든 정상 수행을 의미적으로 판정했다는 뜻은 아니다. 현재이미지 일치도 실제 손가락 정답을 보장하지 않으며 가려진 부위의 정밀 각도는 여전히 알 수 없다. 연속 근거가 부족한 구간을 정상·정답 또는 수정방향으로 단정할 수 없다.

다음 작업
연구용 비교 화면에서 차이값과 근거 부족 시간을 같이 읽도록 정리하고, 근거가 실제 충분한 구간에 한해 피드백 표현을 연결한다. 현재 확인된 부족 원인을 미요청/현재영상불일치/원본미관측으로 나눠 필요한 다음 실험만 진행한다. 정상 허용범위·교정 방향·실제 인식 향상은 별도 공개 검증 없이 채택하지 않는다. 기존 C·T3F·E3와 운영환경을 유지하며 전체 개선 목표를 계속 진행한다.
'''
 (R.U/'RESULT_KO.txt').write_text(text,encoding='utf8')
 template='''<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>참고별 차이와 관측 근거</title><style>body{margin:0;background:#f1f5f9;color:#162638;font-family:system-ui,"Malgun Gothic",sans-serif}main{max-width:1160px;margin:auto;padding:36px 24px}h1{font-size:30px;margin:6px 0 16px}h2{font-size:21px}p{line-height:1.7}header,section{background:white;padding:28px;border-radius:16px;margin-bottom:20px;box-shadow:0 3px 14px #1231}.small{font-size:14px;color:#536476}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.stat{background:#edf5fa;padding:18px;border-radius:10px}.stat strong{font-size:27px;display:block}.controls{display:flex;gap:14px;flex-wrap:wrap}select{padding:12px;border:1px solid #bbcbd5;border-radius:7px;font-size:15px}.card{border:1px solid #dbe5ec;margin:16px 0;padding:18px;border-radius:10px}canvas{width:100%;height:230px;display:block}.legend span{display:inline-block;margin-right:16px}.blue{color:#286ca8}.green{color:#147963}.orange{color:#a35e14}details{margin-top:24px}pre{font:15px/1.8 system-ui;white-space:pre-wrap}table{border-collapse:collapse;width:100%;font-size:13px}td,th{text-align:left;border-bottom:1px solid #e4eaf0;padding:8px}.scroll{max-height:320px;overflow:auto}.images{display:grid;gap:14px}.images img{width:100%;border:1px solid #ddd;border-radius:10px}@media(max-width:700px){.stats{grid-template-columns:1fr}main{padding:12px}section{padding:16px}}</style><main><header><div class="small">공개 자료 연구용 비교 · 운영 모델 변경 없음</div><h1>차이가 작아도, 확인 근거는 따로 봅니다</h1><p>같은 단어를 수행한 <b>공개 영상 1개와 다른 사람의 참고 2개</b>를 각각 비교했습니다. 기존 좌표와 차이값은 유지하고, 손가락별로 이미지 재확인 정보를 붙였습니다.</p><div class="stats"><div class="stat"><strong>100단어 · 300영상</strong>서로 다른 기록ID · 200비교쌍</div><div class="stat"><strong>__POINT__</strong>양쪽 이미지 근거가 연결된 순간각도 칸</div><div class="stat"><strong>__RATE__</strong>원본 비교 가능칸 중 이미지 근거 비율<br><b>인식률·정답률이 아닙니다</b></div></div></header><section><h2>단어별로 두 참고를 나란히 확인하기</h2><p class="small">파란 선은 원본 좌표로 계산한 차이입니다. 초록 표시는 두 영상에서 같은 시점의 각도에 MP 이미지 근거가 있는 곳입니다. 회색 구간은 좌표 차이를 계산할 수 없는 곳입니다. 손내림·가림·검출 실패를 이 표시만으로 구별하거나 오류로 단정하지 않습니다.</p><div class="controls"><select id="word"></select><select id="side"><option value="0">촬영자의 왼손</option><option value="1">촬영자의 오른손</option></select><select id="channel"></select></div><p id="query" class="small"></p><div class="legend small"><span class="blue">━ 좌표 차이</span><span class="green">┃ MP 재확인 근거</span><span class="orange">• YOLO 불일치 별도 표시</span></div><div id="cards"></div></section><section><h2>어떻게 해석해야 하나요?</h2><p><b>차이가 작다:</b> 관측된 2차원 좌표가 참고와 비슷하다는 뜻입니다. 손 모양이 정확하다거나 수어를 올바르게 수행했다는 판정은 아닙니다.</p><p><b>재확인 근거가 없다:</b> 다시 확인하지 않았거나, 손의 좌우·모양·위치가 불확실할 수 있습니다. 이 경우에도 원래 비교 수치를 삭제하지 않고 근거 상태를 함께 남깁니다.</p><p><b>YOLO 불일치:</b> 다른 검출 결과와 엇갈린다는 감사 정보입니다. 이것만으로 정상 손을 버리거나 사용자가 틀렸다고 판단하지 않습니다.</p><details><summary>검증 범위와 남은 문제</summary><pre>__TEXT__</pre></details></section><section><h2>현재 영상에서 직접 확인한 표본</h2><p class="small">같은 원본 장면의 좌표를 겹쳐 표시했습니다. 화면 확대는 검토용이며 원본 검출·학습 범위를 바꾸지 않습니다. 네 장면의 육안 검토는 전체 관절 정답 주석을 대신하지 않습니다.</p><div class="images">__IMAGES__</div></section></main><script>const DATA=__DATA__;
const labels=['엄지 1','엄지 2','엄지 3','검지 1','검지 2','검지 3','중지 1','중지 2','중지 3','약지 1','약지 2','약지 3','소지 1','소지 2','소지 3','손바닥 가로','손바닥 세로','팔꿈치 가로','팔꿈치 세로','팔 손목 가로','팔 손목 세로','손 손목 가로','손 손목 세로'];
const states=['좌표 미관측/각도 계산 불가','재확인 안 함','재확인 영상 쌍 부족','좌우 근거 불확실','모양·위치 재확인 불일치','MP 이미지 근거 있음','시간 보간 양끝의 근거 상태가 다름'];
const $=id=>document.getElementById(id);DATA.forEach((q,i)=>$('word').add(new Option(q.label+' · '+q.word,i)));labels.forEach((v,i)=>$('channel').add(new Option(v,i)));
function plot(canvas,r,h,c){const ctx=canvas.getContext('2d');canvas.width=1040;canvas.height=230;const W=950,H=155,x0=58,y0=20,t=r.time,n=t.length;const values=r.difference.map(v=>v[h][c]);const max=Math.max(c<15?5:.05,...values.filter(v=>v!==null));const xx=i=>x0+(t[i]-t[0])/(t[n-1]-t[0]||1)*W;const yy=v=>y0+H-v/max*H;ctx.clearRect(0,0,1040,230);ctx.fillStyle='#dfe5eb';for(let i=0;i<n;i++)if(!r.raw[i][h][c])ctx.fillRect(xx(i)-2,y0,Math.max(3,W/n),H);ctx.strokeStyle='#b6c4d0';ctx.beginPath();ctx.moveTo(x0,y0);ctx.lineTo(x0,y0+H);ctx.lineTo(x0+W,y0+H);ctx.stroke();ctx.strokeStyle='#286ca8';ctx.lineWidth=2;ctx.beginPath();let start=true;values.forEach((v,i)=>{if(v===null){start=true;return}if(start)ctx.moveTo(xx(i),yy(v));else ctx.lineTo(xx(i),yy(v));start=false;});ctx.stroke();for(let i=0;i<n;i++){if(r.after[i][h][c]){ctx.fillStyle='#147963';ctx.fillRect(xx(i)-1,y0+H+10,3,13)}if(c<15&&r.yolo_audit[i][h][c]){ctx.fillStyle='#b76816';ctx.fillRect(xx(i)-1,y0+H+27,3,4)}}ctx.fillStyle='#536476';ctx.font='14px sans-serif';ctx.fillText(max.toFixed(c<15?1:3),2,27);ctx.fillText('0',36,y0+H);ctx.fillText(t[0].toFixed(2)+'초',x0,220);ctx.fillText(t[n-1].toFixed(2)+'초 (참고 시간)',x0+W-145,220);}
function render(){const q=DATA[+$('word').value],h=+$('side').value,c=+$('channel').value;$('query').textContent='비교 영상: '+q.query+' (기록ID '+q.query_id+')';$('cards').replaceChildren();for(const r of q.references){const div=document.createElement('div');div.className='card';const title=document.createElement('h2');title.textContent='참고 기록ID '+r.reference_id;div.append(title);const raw=r.raw.reduce((a,v)=>a+v[h][c],0),bf=r.before.reduce((a,v)=>a+v[h][c],0),af=r.after.reduce((a,v)=>a+v[h][c],0);const p=document.createElement('p');p.className='small';p.textContent=c<15?'순간 차이 계산 가능 '+raw+'칸 · 이미지 근거 '+bf+' → '+af+'칸 · 단위: 화면에 투영된 각도 차이(도)':'위치 차이 계산 가능 '+raw+'칸 · 단위: 어깨너비에 대한 비율 · 위치의 정밀 정확도를 검증한 수치가 아닙니다';div.append(p);const canvas=document.createElement('canvas');div.append(canvas);const dt=document.createElement('details'),sm=document.createElement('summary');sm.textContent='시간별 값과 근거 보기';dt.append(sm);const sc=document.createElement('div');sc.className='scroll';const tab=document.createElement('table');tab.innerHTML='<tr><th>참고/비교 시간</th><th>차이</th><th>비교 영상 근거</th><th>참고 근거</th></tr>';r.time.forEach((t,i)=>{const tr=document.createElement('tr');const d=r.difference[i][h][c];const a=[t.toFixed(2)+' / '+r.query_time[i].toFixed(2)+'초',d===null?'비교 불가':d.toFixed(c<15?1:3),c<15?states[r.query_state[i][h][c]]:'원본 위치 관측',c<15?states[r.reference_state[i][h][c]]:'원본 위치 관측'];a.forEach(v=>{const td=document.createElement('td');td.textContent=v;tr.append(td)});tab.append(tr)});sc.append(tab);dt.append(sc);div.append(dt);$('cards').append(div);plot(canvas,r,h,c)}}['word','side','channel'].forEach(id=>$(id).addEventListener('change',render));render();</script></html>'''
 vi=R.read(R.U/'VISUAL_INDEX.json');images=''.join('<img alt="'+html.escape(x['kind'])+'" src="visual/'+Path(x['image']).name+'">' for x in vi['rows']);payload=json.dumps(data,ensure_ascii=False,allow_nan=False,separators=(',',':')).replace('</','<\/');page=template.replace('__POINT__',f"{cc['point_before']:,} → {cc['point_after']:,}").replace('__RATE__',pct(cc['point_after'],cc['raw_point_angles'])).replace('__TEXT__',html.escape(text)).replace('__IMAGES__',images).replace('__DATA__',payload);(R.U/'RESULT_KO.html').write_text(page,encoding='utf8');R.write(R.U/'REPORT_CHECK.json',dict(at=R.now(),words=len(data),pairs=sum(len(x['references']) for x in data),data_sha256=R.sha(R.U/'VIEW_DATA.json'),html_sha256=R.sha(R.U/'RESULT_KO.html'),text_sha256=R.sha(R.U/'RESULT_KO.txt'),verified_result=R.sha(R.U/'INTEGRATION_VERIFIED.json'),rendered_browser=False));print(text,flush=True)
